static void testPhysicalModel(const File& root,Assets& assets){
    bool stable=true;for(double rate:{8000.,44100.,48000.,96000.,192000.})for(int mode:{0,1})for(int pitch:{0,60,127})for(int extreme:{0,1}){
        SynthVoice voice;SynthPatch p;p.physical={mode,extreme?20.f:.1f,(float)extreme,extreme?1.f:.05f,extreme?.95f:.05f,(float)extreme,(float)extreme};p.cutoff=20000;p.resonance=1;p.coarse=extreme?24:-24;p.sustain=1;voice.start(pitch,rate,123,extreme?24000:-24000);
        for(int i=0;i<12000;++i){if(i==4000){p.physical.mode=1-mode;p.physical.position=.5f;p.physical.decay=1;}auto v=voice.process(p,4,i<6000,.001f,.02f);stable&=std::isfinite(v)&&std::abs(v)<.56;}
        stable&=!voice.active();
    }expect(stable,"physical model extremes across supported sample rates, live edits and microtuning stay bounded and release");
    for(double rate:{8000.,44100.,48000.,96000.,192000.})for(int mode:{0,1})for(int pitch:{48,69,84}){
        PhysicalVoice v;v.start(rate);PhysicalSettings p;p.mode=mode;p.decay=10;p.damping=1;p.brightness=.05f;p.position=.45f;p.body=0;p.stiffness=0;double hz=440*std::exp2((pitch-69)/12.),previous=0;int first=-1,last=-1,count=0;
        for(int i=0;i<(int)(rate*.8);++i){auto x=v.process(p,hz);if(i>rate*.35&&previous<=0&&x>0){if(first<0)first=i;last=i;++count;}previous=x;}
        double actual=(count-1)*rate/(last-first);expect(count>4&&std::abs(1200*std::log2(actual/hz))<2,"string and bar fundamentals track played pitch within two cents across rates");
    }
    PhysicalVoice sustained;sustained.start(48000);PhysicalSettings extreme;extreme.decay=20;extreme.damping=0;extreme.brightness=1;extreme.position=.05f;extreme.body=extreme.stiffness=1;bool longStable=true;for(int i=0;i<48000*60;++i){if(i%48000==0)extreme.mode=1-extreme.mode;auto x=sustained.process(extreme,110);longStable&=std::isfinite(x)&&std::abs(x)<=1.000001;}expect(longStable,"sixty seconds at maximum decay with body resonance and live model switches remains finite and bounded");
    SynthVoice tuned;tuned.start(69,48000,123,50);SynthPatch tunedPatch;tunedPatch.sustain=1;tunedPatch.coarse=3;tunedPatch.cutoff=18000;tunedPatch.physical.brightness=.05f;tunedPatch.physical.damping=1;tunedPatch.physical.position=.45f;tunedPatch.physical.body=tunedPatch.physical.stiffness=0;double previous=0;int first=-1,last=-1,count=0;for(int i=0;i<48000;++i){auto x=tuned.process(tunedPatch,4,true,.001f,.3f);if(i>24000&&previous<=0&&x>0){if(first<0)first=i;last=i;++count;}previous=x;}double actual=(count-1)*48000./(last-first),target=440*std::exp2(3.5/12);expect(count>4&&std::abs(1200*std::log2(actual/target))<2,"physical SynthVoice combines onset microtuning and instrument coarse tuning in actual audio");
    PhysicalVoice decay;decay.start(48000);PhysicalSettings d;d.decay=1;d.damping=0;d.body=0;double early=0,late=0;for(int i=0;i<48000;++i){auto x=decay.process(d,440);if(i<4800)early+=x*x;if(i>=43200)late+=x*x;}expect(late<early*.00002&&late>0,"physical decay actually damps modal energy by the specified T60");
    auto p=emptyProject();p.loop=false;p.bpm=120;auto& t=p.tracks[7];t.instrument=Instrument::physical;t.synth=factorySynthPresets()[64].patch;t.attack=.001f;t.release=.4f;t.send=0;t.volume=.7f;t.tuning.enabled=true;t.tuning.cents[60]=50;p.patterns[0].length=4;p.patterns[0].lanes[7]={{0,1,60,.8f},{.1,.9,64,.6f},{.2,.8,67,.6f}};
    auto a=render(p,assets,root,48000,127),b=render(p,assets,root,48000,733);bool same=true;for(int ch=0;ch<2;++ch)for(int i=0;i<48000;++i)same&=a.getSample(ch,i)==b.getSample(ch,i);expect(same&&a.getMagnitude(0,0,48000)>.001,"polyphonic microtuned physical model is audible and independent of block size");
    auto bar=p;bar.tracks[7].synth.physical.mode=1;b=render(bar,assets,root,24000);double difference=0;for(int i=0;i<24000;++i)difference+=std::abs(a.getSample(0,i)-b.getSample(0,i));expect(difference>1,"struck bar modes create a different audible result from plucked strings");
    auto json=projectToJson(p);Project loaded;expect(projectFromJson(json,loaded).wasOk()&&loaded.tracks[7].synth==t.synth&&loaded.tracks[7].instrument==Instrument::physical,"schema twenty-four embeds complete physical instrument state");json.getDynamicObject()->setProperty("schema",23);expect(projectFromJson(json,loaded).failed(),"physical instruments reject mislabeled legacy projects");json=projectToJson(p);(*json["tracks"].getArray())[7]["synth"].getDynamicObject()->removeProperty("physical");expect(projectFromJson(json,loaded).failed(),"current projects require complete physical settings");
    for(auto key:{"mode","decay","damping","brightness","position","body","stiffness"}){for(auto bad:{var(true),var("0.5"),var(std::nan("")),var(30)}){auto patch=synthPatchToJson(t.synth);patch["physical"].getDynamicObject()->setProperty(key,bad);auto saved=t.synth;expect(synthPatchFromJson(patch,saved,true,true,true).failed()&&saved==t.synth,"malformed physical settings reject atomically");}}
    for(int i=41;i<48;++i){auto track=t;auto spec=synthParameterSpecs()[(size_t)i];double v=i==41?1:(spec.low+spec.high)*.5;expect(setSynthParameter(track,i,v).wasOk()&&std::abs(synthParameterValue(track,i)-v)<1e-5,"physical controls use validated actual-unit edits");}
    auto sound=factorySynthPresets()[64];auto soundJson=synthPresetToJson(sound);SynthPreset read;expect((int)soundJson["schema"]==4&&synthPresetFromJson(soundJson,read).wasOk()&&read.patch==sound.patch,"physical sound files use schema four with complete patch state");soundJson.getDynamicObject()->setProperty("schema",3);expect(synthPresetFromJson(soundJson,read).failed(),"physical sounds cannot be mislabeled as old sound files");
    SoundLibrary library;library.personal.push_back({"user-physical",sound});library.favorites.add(factorySoundId(factorySynthPresets()[70]));SoundLibrary readLibrary;auto lib=soundLibraryToJson(library);expect((int)lib["schema"]==4&&soundLibraryFromJson(lib,readLibrary).wasOk()&&readLibrary.personal[0].sound.patch==sound.patch,"physical sounds and factory favorites persist in sound library schema four");lib.getDynamicObject()->setProperty("schema",3);expect(soundLibraryFromJson(lib,readLibrary).failed(),"legacy library labels cannot hide physical instruments");
    for(auto instrument:{Instrument::analog,Instrument::fm,Instrument::wavetable,Instrument::additive}){auto legacy=p;legacy.tracks[7].instrument=instrument;legacy.tracks[7].synth={};auto old=projectToJson(legacy);old.getDynamicObject()->setProperty("schema",23);for(auto& row:*old["tracks"].getArray())row["synth"].getDynamicObject()->removeProperty("physical");expect(projectFromJson(old,loaded).wasOk()&&loaded.tracks[7].synth==legacy.tracks[7].synth,"older synth projects gain neutral physical settings");}
    RenderSettings settings;settings.bits=32;settings.tailSeconds=0;auto file=root.getChildFile("physical-export.wav");auto result=renderAudio(p,assets,root,file,settings);AudioFormatManager fm;fm.registerBasicFormats();std::unique_ptr<AudioFormatReader> reader(fm.createReaderFor(file));AudioBuffer<float> decoded(2,48000);same=result.wasOk()&&reader;if(same){reader->read(&decoded,0,48000,0,true,true);for(int ch=0;ch<2;++ch)for(int i=0;i<48000;++i)same&=decoded.getSample(ch,i)==a.getSample(ch,i);}expect(same,"physical float export matches callback audio exactly");
    auto ops=JSON::parse(R"([{"op":"set_track","track":7,"instrument":"physical","preset":"Cedar string","synth":{"physical":{"mode":1,"decay":6,"damping":0.3,"brightness":0.8,"position":0.2,"body":0.4,"stiffness":0.1}}}])");Project edited;expect(applyControlEdits(p,ops,edited).wasOk()&&edited.tracks[7].synth.physical.mode==1&&edited.tracks[7].synth.physical.decay==6,"MCP creates custom physical instruments with complete validated model settings");auto sentinel=JSON::toString(projectToJson(edited));(*ops.getArray())[0]["synth"]["physical"].getDynamicObject()->removeProperty("body");expect(applyControlEdits(p,ops,edited).failed()&&JSON::toString(projectToJson(edited))==sentinel,"incomplete physical MCP edits leave the destination untouched");
}
